{"code":"def transform(grid):
    pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v]
    # If pixels are isolated (as in the demonstrated separated diagonal), compact them.
    S=set(pts); comps=[]
    while S:
        q=[S.pop()]; comp=[]
        while q:
            p=q.pop(); comp.append(p)
            for d in ((1,0),(-1,0),(0,1),(0,-1)):
                z=(p[0]+d[0],p[1]+d[1])
                if z in S: S.remove(z); q.append(z)
        comps.append(comp)
    if len(comps)>1:
        return [[grid[r][c] for r,c in sorted(pts)]]
    r0=min(r for r,c in pts); r1=max(r for r,c in pts); c0=min(c for r,c in pts); c1=max(c for r,c in pts)
    a=[row[c0:c1+1] for row in grid[r0:r1+1]]
    return [row+row for row in a]"}

